export const MONUMENTS = JSON.parse("[{\"id\":\"n1450164801\",\"kind\":\"memorial\",\"sub\":\"statue\",\"name\":\"И. С. Тургенев\",\"x\":-696.8,\"z\":-427.6,\"h\":4.5,\"startDate\":\"2001-08-14\",\"subject\":\"Q42831\",\"artist\":\"Ян Нейман, В. Свешников\"},{\"id\":\"n3511128450\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Карл Росси\",\"x\":-583,\"z\":-372.6,\"subject\":\"Q619584\"},{\"id\":\"n3511128451\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Джакомо Кваренги\",\"x\":-571.2,\"z\":-382.3,\"subject\":\"Q128623\"},{\"id\":\"n3511128452\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Антонио Ринальди\",\"x\":-573.3,\"z\":-397.4,\"subject\":\"Q19165\"},{\"id\":\"n3511128454\",\"kind\":\"memorial\",\"sub\":\"bust\",\"name\":\"Бартоломео Растрелли\",\"x\":-585.2,\"z\":-403.6,\"subject\":\"Q299687\"},{\"id\":\"n8901842644\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. И. Ленину\",\"x\":-663.9,\"z\":-415.1,\"subject\":\"Q1394\",\"inscription\":\"Здесь, в бывшем манеже, 15 апреля 1917 года на митинге солдат броневого дивизиона, 1 января 1918 года на собрании сводного отряда красногвардейцев, отправлявшихся на Западный фронт, выступал Владимир Ильич Ленин\"},{\"id\":\"n6358872948\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1566.5,\"z\":-390.6,\"subject\":\"Q4424524\",\"inscription\":\"В этом доме в 1830х годах находились библиотека и книжная лавка известного книгоиздателя Александра Филипповича Смирдина. Здесь встречались А.С. Пушкин, И.А. Крылов, В.А. Жуковский, Н.В. Гоголь и другие русские писатели и поэты.\"},{\"id\":\"n6893148685\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728,\"z\":-373.8,\"material\":\"granite\"},{\"id\":\"n6903094628\",\"kind\":\"artwork\",\"sub\":\"sculpture\",\"name\":\"Сфинкс\",\"x\":-1728.3,\"z\":-372.7,\"material\":\"granite\"},{\"id\":\"n13272985734\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-1539.7,\"z\":-383.4},{\"id\":\"n6077061649\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Е. А. Мравинскому\",\"x\":-1107.6,\"z\":-432.1,\"subject\":\"Q320609\",\"inscription\":\"Евгений Мравинский творил здесь LVI лет\"},{\"id\":\"n6484449100\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"В. Ф. Комиссаржевской\",\"x\":-884.9,\"z\":-408.9,\"subject\":\"Q436876\",\"inscription\":\"В этом здании с 1904 г. по 1906 г. помещался Драматический театр, которым руководила выдающаяся русская артистка Вера Фёдоровна Комиссаржевская\"},{\"id\":\"n13237208814\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"x\":-925.8,\"z\":-392.4,\"inscription\":\"Вечная слава сотрудникам универмага павшим в боях с немецко-фашистскими захватчиками за свободу и независимость нашей родины в Великой отечественной войне 1941-1945\"},{\"id\":\"n4683728170\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. И. Вавилову\",\"x\":-2021.9,\"z\":-437.9,\"subject\":\"Q214926\",\"inscription\":\"В этом доме с 1928 по 1940 г. жил выдающийся биолог, академик Николай Иванович Вавилов\"},{\"id\":\"n4683728171\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Н. П. Акимову\",\"x\":-2028.7,\"z\":-411.6,\"subject\":\"Q1185061\",\"inscription\":\"В этом доме с 1945 г. по 1967 г. жил народный артист СССР Николай Павлович Акимов\"},{\"id\":\"n4683728172\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Н. Кононову\",\"x\":-2053.9,\"z\":-412.7,\"subject\":\"Q765371\",\"inscription\":\"В этом доме жил с 1968 по 1986 год выдающийся учёный-востоковед академик Андрей Николаевич Кононов\"},{\"id\":\"n10126606281\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. С. Грибоедову\",\"x\":-1891.8,\"z\":-384.3,\"subject\":\"Q15001\",\"inscription\":\"В этом доме в 1828 году жил Александр Сергеевич Грибоедов\"},{\"id\":\"n5854740072\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Ф. Э. Дзержинскому\",\"x\":-2277.2,\"z\":-438,\"subject\":\"Q188570\",\"inscription\":\"В этом доме с 7 (20) декабря 1917 года по 10 (23) марта 1918 года находилась Всероссийская Чрезвычайная Комиссия по борьбе с контрреволюцией и саботажем, которую возглавлял [...] Феликс Эдмундович Дзержинский\",\"description\":\"Из-за ограничений на длину текста пропущен следующий фрагмент: \\\"выдающийся деятель Коммунистической партии и Советского государства, ближайший соратник В.И. Ленина\\\"\"},{\"id\":\"n5854766833\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. О. Дунаевскому\",\"x\":-2257.7,\"z\":-412.2,\"subject\":\"Q638638\",\"inscription\":\"В этом доме с 1936 по 1941 год жил и работал выдающийся композитор Исаак Осипович Дунаевский\"},{\"id\":\"n5854766836\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"А. Я. Вагановой\",\"x\":-2250.7,\"z\":-402.8,\"subject\":\"Q236413\",\"inscription\":\"Здесь с 1937 года по 1951 год жила Агриппина Яковлевна Ваганова, профессор, крупнейший деятель советской хореографии\"},{\"id\":\"n5854766837\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"С. П. Преображенской\",\"x\":-2249.2,\"z\":-400.8,\"subject\":\"Q4377282\",\"inscription\":\"В этом доме с 1937 по 1966 год жила народная артистка СССР, лауреат Государственных премий СССР, профессор Софья Петровна Преображенская\"},{\"id\":\"n5854766838\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"И. В. Ершову\",\"x\":-2253.3,\"z\":-406.3,\"subject\":\"Q4176892\",\"inscription\":\"В этом доме с 1931 по 1941 год жил великий русский певец, профессор Ленинградской консерватории, народный артист СССР Иван Васильевич Ершов\"},{\"id\":\"n5854766842\",\"kind\":\"memorial\",\"sub\":\"plaque\",\"name\":\"Г. А. Алиеву\",\"x\":-2229.9,\"z\":-375.5,\"subject\":\"Q157451\",\"inscription\":\"В этом доме, в Высшей школе МГБ СССР в 1949-1950 гг. учился выдающийся государственный деятель, президент Азербайджанской республики Гейдар Алиевич Алиев\"}]");
